CREATE COLUMN TABLE "TEST_AP"."OBAL" ("AbsEntry" INTEGER CS_INT NOT NULL , "ItemCode" NVARCHAR(50) NOT NULL , "WhsCode" NVARCHAR(8) NOT NULL , "PeriodID" INTEGER CS_INT NOT NULL , "EvalSystem" NVARCHAR(1) DEFAULT 'W' NOT NULL , "DtSorting" NVARCHAR(1) DEFAULT 'P' NOT NULL , "LayerID" INTEGER CS_INT DEFAULT -1 NOT NULL , "CreateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "OBAL_SECONDARY" ON "TEST_AP"."OBAL" ( "ItemCode" ASC, "WhsCode" ASC, "PeriodID" ASC, "EvalSystem" ASC, "DtSorting" ASC, "LayerID" ASC )